#include "inputs/audit_helpers.hpp"
J Nj(const hyp::LayerPoint<double>&p,const std::array<double,3>&n,int i){J y{D(n[i])};for(int k=0;k<3;++k){y.d[k]=((k==i?1.:0.)-n[k]*n[i])/p.radius;for(int l=0;l<3;++l)y.dd[k][l]=(-(k==i?1.:0.)*n[l]-(l==i?1.:0.)*n[k]-(k==l?1.:0.)*n[i]+3*n[i]*n[k]*n[l])/(p.radius*p.radius);}return y;}
J Pow(const J&x,int m){J y(D(1));for(int i=0;i<m;++i)y=y*x;return y;}
J Ang(const hyp::LayerPoint<double>&p,const std::array<double,3>&n,int mode){auto y=Nj(p,n,1),z=Nj(p,n,2);switch(mode){case 0:return J(D(1));case 1:return y;case 2:return z;case 3:return y*y;case 4:return y*z;default:return z*z;}}
J FullBasis(const hyp::LayerPoint<double>&p,const std::array<double,3>&n,int mode){auto O=OmegaJ(p),y=Nj(p,n,1),z=Nj(p,n,2);switch(mode){case 0:return J(D(1));case 1:return O;case 2:return y;case 3:return z;case 4:return O*O;case 5:return O*y;case 6:return O*z;case 7:return y*y;case 8:return y*z;default:return z*z;}}
Jet Initial(const hyp::LayerPoint<double>&p,const std::array<double,3>&n,int col){auto u=Lift(p.state);if(col<10){const auto f=FullBasis(p,n,col);J h(D(p.alpha));for(int i=0;i<3;++i){h.d[i]=p.state.alpha.d[i];for(int j=0;j<3;++j)h.dd[i][j]=p.state.alpha.dd[i][j];}Seed(u,0,Linear(h*f));for(int i=0;i<3;++i){J b(D(p.state.beta.value[i]));for(int k=0;k<3;++k){b.d[k]=p.state.beta.d[k][i];for(int l=0;l<3;++l)b.dd[k][l]=p.state.beta.dd[k][l][i];}Seed(u,4+i,Linear(b*f));}}
 else if(col<64){int c=col-10,ang=c%6,j=(c/6)%3,m=c/18;const auto amp=Pow(OmegaJ(p),m)*Ang(p,n,ang);for(int i=0;i<3;++i)Seed(u,4+i,Linear(amp*(J(D(i==j?1.:0.))-Nj(p,n,i)*Nj(p,n,j))));}
 else{auto amp=Pow(OmegaJ(p),2)*Ang(p,n,col-64);for(int i=0;i<3;++i)Seed(u,4+i,Linear(amp*Nj(p,n,i)));}Consistent(u);return u;}
struct Evaluation{std::array<double,20>F{};double dg[3][3][3]{},ndot=0,qdot=0,transport_error=0,geom_error=0,C_error=0;};
Evaluation Evaluate(const hyp::LayerPoint<double>&p,const std::array<double,3>&n,const Jet&u,double a,double sigma){Evaluation e;auto f=Parts(p,u,10,sigma,true);for(int k=0;k<20;++k)e.F[k]=f.r[k].d+f.s[k].d/p.omega;const auto cc=Constraints(u,p);for(double c:cc)e.C_error=std::max(e.C_error,std::abs(c));
 double iso=2*u.alpha.value.d/a;for(int k=0;k<3;++k)iso-=2*u.beta.value[k].d*p.domega[k];iso/=p.omega;double diso[3]{};for(int z=0;z<3;++z){diso[z]=2*u.alpha.d[z].d/a;for(int k=0;k<3;++k)diso[z]-=2*(u.beta.d[z][k].d*p.domega[k]+u.beta.value[k].d*p.omega_hessian[z][k]);diso[z]=(diso[z]-iso*p.domega[z])/p.omega;}
 double bar[3][3]{},dbar[3][3][3]{},chi=0,dchi[3]{};for(int i=0;i<3;++i)for(int j=0;j<3;++j){bar[i][j]=u.beta.d[i][j].d+u.beta.d[j][i].d+(i==j?iso:0);for(int z=0;z<3;++z)dbar[z][i][j]=u.beta.dd[z][i][j].d+u.beta.dd[z][j][i].d+(i==j?diso[z]:0);if(i==j){chi-=bar[i][j]/3;for(int z=0;z<3;++z)dchi[z]-=dbar[z][i][j]/3;}}
 const int ti[5]={0,0,0,1,1},tj[5]={0,1,2,1,2};e.geom_error=std::abs(chi-e.F[1]);double lap=0,Pfield=0;for(int i=0;i<3;++i){lap+=u.alpha.dd[i][i].d;Pfield-=3*p.radius*n[i]*u.alpha.d[i].d/a;}Pfield+=-p.omega*lap+3*u.alpha.value.d/a;e.geom_error=std::max(e.geom_error,std::abs(Pfield-e.F[2]));e.geom_error=std::max(e.geom_error,std::abs(e.F[3]));
 for(int i=0;i<3;++i){double lam=0;for(int j=0;j<3;++j){for(int z=0;z<3;++z)e.dg[z][i][j]=dbar[z][i][j]+(i==j?dchi[z]:0);lam+=e.dg[j][j][i];}e.geom_error=std::max(e.geom_error,std::abs(lam-e.F[17+i]));}
 for(int k=0;k<5;++k){const int i=ti[k],j=tj[k];e.geom_error=std::max(e.geom_error,std::abs(bar[i][j]+(i==j?chi:0)-e.F[7+k]));e.geom_error=std::max(e.geom_error,std::abs(-u.alpha.dd[i][j].d+(i==j?lap/3:0)-e.F[12+k]));}
 const auto om=Omega(u,p);double wdot=om.normal.v*e.F[0],Gdot=e.F[1]*p.radius*p.radius/(a*a);for(int i=0;i<3;++i)wdot+=p.domega[i]*e.F[4+i];wdot/=-p.alpha;double gm[3][3]{};for(int k=0;k<5;++k)gm[ti[k]][tj[k]]=gm[tj[k]][ti[k]]=e.F[7+k];gm[2][2]=-gm[0][0]-gm[1][1];for(int i=0;i<3;++i)for(int j=0;j<3;++j)Gdot-=gm[i][j]*p.domega[i]*p.domega[j];e.ndot=Gdot-2*om.normal.v*wdot;e.qdot=e.F[2]-3*wdot;
 // Independent radial transport identity for arbitrary angular gauge jets.
 const double r=p.radius,h=p.alpha,br=0;double b=0,bp=0;for(int i=0;i<3;++i){b+=n[i]*u.beta.value[i].d;for(int z=0;z<3;++z)bp+=n[z]*n[i]*u.beta.d[z][i].d;}b+=r*u.alpha.value.d/(a*h);double ar=0;for(int z=0;z<3;++z)ar+=n[z]*u.alpha.d[z].d;bp+=u.alpha.value.d/(a*h)+r*ar/(a*h)-r*r*u.alpha.value.d/(a*a*h*h);
 const double fac=2*r*r*r/(a*a*a*h*h),facp=fac*(3/r-2*r/(a*h));const double N=fac*b,Np=fac*bp+facp*b,T=-(r*r*r*r+6*r*r+1)/(4*a*r),react=(std::pow(r,6)+(16*sigma-29)*std::pow(r,4)+15*r*r-3)/(4*a*r*r*(r*r-1));e.transport_error=std::abs(e.ndot-T*Np-react*N);return e;}
int main(){double initC=0,initR0=0,geom=0,transport=0;std::cout<<std::setprecision(17)<<"{\"controls\":[";bool first=true;for(double a:{.5,.75,1.,2.})for(double sigma:{3.,5.})for(int dir=0;dir<2;++dir){const std::array<double,3>n=dir?std::array<double,3>{.36,-.48,.8}:std::array<double,3>{1,0,0};hyp::LayerReference<double>ref(1,a,{true,.05,.95});const auto p0=ref.At(n[0],n[1],n[2]);for(int col=0;col<70;++col){auto init=Initial(p0,n,col);auto ir=Parts(p0,init,10,sigma,true);for(auto q:ir.s)initR0=std::max(initR0,std::abs(q.d));auto ic=Constraints(init,p0);for(double c:ic)initC=std::max(initC,std::abs(c));double N1t[3]{};std::array<double,20>F{};double dg[3][3][3]{};const double w[4]={4,-6,4,-1};
 for(int level=0;level<3;++level)for(int k=0;k<4;++k){double O=std::ldexp(.001,-level)*(k+1);const double r=std::sqrt(1-2*a*O);auto p=ref.At(r*n[0],r*n[1],r*n[2]);auto u=Initial(p,n,col);auto ev=Evaluate(p,n,u,a,sigma);geom=std::max(geom,ev.geom_error);transport=std::max(transport,ev.transport_error);N1t[level]+=w[k]*ev.ndot/p.omega;if(level==2){for(int i=0;i<20;++i)F[i]+=w[k]*ev.F[i];for(int z=0;z<3;++z)for(int i=0;i<3;++i)for(int j=0;j<3;++j)dg[z][i][j]+=w[k]*ev.dg[z][i][j];}}
 auto next=Lift(p0.state);for(int i=0;i<20;++i){J s{D(F[i])};if(i>=7&&i<12){const int ti[5]={0,0,0,1,1},tj[5]={0,1,2,1,2};for(int z=0;z<3;++z)s.d[z]=dg[z][ti[i-7]][tj[i-7]];}if(i==2){double lap=0;for(int z=0;z<3;++z)lap+=init.alpha.dd[z][z].d;for(int z=0;z<3;++z){double an=0;for(int j=0;j<3;++j)an+=init.alpha.dd[z][j].d*n[j];s.d[z]=(n[z]*lap-3*an)/a;}}Seed(next,i,Linear(s));}Consistent(next);auto nr=Parts(p0,next,10,sigma,true);double R=0;for(auto q:nr.s)R=std::max(R,std::abs(q.d));auto nc=Constraints(next,p0);double C=0;for(double q:nc)C=std::max(C,std::abs(q));
 if(!first)std::cout<<',';first=false;std::cout<<"{\"a\":"<<a<<",\"sigma\":"<<sigma<<",\"dir\":"<<dir<<",\"col\":"<<col<<",\"N1_t\":["<<N1t[0]<<','<<N1t[1]<<','<<N1t[2]<<"],\"next_R0_error\":"<<R<<",\"next_leading_constraints_error\":"<<C<<'}';}}
 std::cout<<"],\"summary\":{\"initial_constraints_error\":"<<initC<<",\"initial_R0_error\":"<<initR0<<",\"actual_ADM_first_RHS_geometry_field_error\":"<<geom<<",\"actual_arbitrary_angular_N_transport_identity_error\":"<<transport<<"}}\n";}
